def fit2d(dT,de):
    cols=[]
    for i in range(dT+1):
        for j in range(de+1):
            cols.append(T**i*eps**j)
    X=np.array(cols).T
    c=np.linalg.lstsq(X,sigma,rcond=None)[0]
    r=sigma-X@c
    return np.mean(r**2)/np.var(sigma)
